def algorithm(func, dim, lb, ub, budget, rng):
    def sample(rng, n):
        return rng.uniform(lb, ub, size=(n, dim))

    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    def fitness(x):
        return func(x)

    pop_size = 50
    restart_threshold = 0.1 * budget
    cma_init_sigma = 10
    cma_decay_rate = 0.01

    best_solution = None
    best_fitness = np.inf
    iteration = 0
    while True:
        if iteration >= budget or (best_solution is not None and (iteration - np.sum(rng.random(pop_size) < restart_threshold)) >= restart_threshold):
            break

        population = sample(rng, pop_size)
        population = clip(population, lb, ub)

        fitness_values = np.array([fitness(x) for x in population])

        if best_solution is None or np.min(fitness_values) < best_fitness:
            best_solution = population[np.argmin(fitness_values)]
            best_fitness = np.min(fitness_values)

        iteration += 1

        sigma = cma_init_sigma * (1 - cma_decay_rate) ** iteration
        sigma = max(sigma, 0.001)

        for i in range(pop_size):
            noise = rng.normal(0, sigma, size=dim)
            population[i] += noise

        population = clip(population, lb, ub)

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    def get_cost(x):
        return func(x)

    def clip_x(x):
        return np.clip(x, lb, ub)

    x_current = rng.uniform(lb, ub, size=dim)
    best_x = x_current
    best_cost = get_cost(clip_x(best_x))
    population_size = 10

    for stage in range(int(np.log2(budget)) + 1):
        if budget < population_size:
            break

        candidate_pool = rng.uniform(lb, ub, size=(population_size, dim))
        costs = [get_cost(clip_x(x)) for x in candidate_pool]
        ranked_indices = np.argsort(costs)

        for i in range(population_size - 1):
            if get_cost(clip_x(candidate_pool[ranked_indices[i]])) < get_cost(
                clip_x(best_x)
            ):
                best_x = candidate_pool[ranked_indices[i]]
                best_cost = costs[ranked_indices[i]]

        budget -= population_size
        population_size //= 2

    return best_x
